133	/**
134	 * The resource a nav-level permission question is asked about. Nav items are
135	 * asked "could this actor do this at all in this org?", so the resource is
136	 * always the actor's own org, shaped for the action's resource kind.
137	 */
138	function navResource(action: PermissionAction, actor: Actor): PermissionResource {
139	  const [domain] = action.split(":");
140	  switch (domain) {
141	    case "org":
142	      return action === "org:manage_billing"
143	        ? { kind: "billing", orgId: actor.orgId }
144	        : { kind: "organization", orgId: actor.orgId };
145	    case "activity":
146	      return { kind: "activity", orgId: actor.orgId };
147	    case "notification":
148	      return { kind: "notification", orgId: actor.orgId, recipientId: actor.userId };
149	    case "webhook":
150	      return { kind: "webhook", orgId: actor.orgId, webhookId: null };
151	    default:
152	      // member / project / issue / comment nav entries are org-wide questions.
153	      return { kind: "organization", orgId: actor.orgId };
154	  }
155	}
156	
157	/**
158	 * A snapshot is normally complete, but a client provider may be holding one
159	 * serialised before a flag existed. Fall back to evaluating the flag directly
160	 * with the conservative context we can build from the actor alone.
161	 */
162	function flagAllows(
163	  flag: FeatureFlagKey,
164	  actor: Actor,
165	  flags: FeatureFlagSnapshot,
166	): boolean {
167	  const snapshotted: boolean | undefined = flags[flag];
168	  if (typeof snapshotted === "boolean") return snapshotted;
169	  return isEnabled(flag, {
170	    orgId: actor.orgId,
171	    userId: actor.userId,
172	    plan: "free",
173	    role: actor.role,
174	  });
175	}
176	
177	/**
178	 * Filters a nav tree down to what `actor` may see, recursing into children.
179	 * A parent whose every child was filtered away and which has no destination
180	 * of its own is dropped too, so the sidebar never renders an empty group.
181	 */
182	export function visibleNav(
183	  items: readonly NavItem[],
184	  actor: Actor,
185	  flags: FeatureFlagSnapshot,
186	): readonly NavItem[] {
187	  const visible: NavItem[] = [];
188	
189	  for (const item of items) {
190	    if (item.flag !== undefined && !flagAllows(item.flag, actor, flags)) {
191	      continue;
192	    }
193	    if (item.action !== undefined && !can(actor, item.action, navResource(item.action, actor))) {
194	      continue;
195	    }
196	
197	    if (item.children === undefined) {
198	      visible.push(item);
199	      continue;
200	    }
201	
202	    const children = visibleNav(item.children, actor, flags);
203	    if (children.length === 0 && item.segment === "") continue;
204	    visible.push({ ...item, children });
205	  }
206	
207	  return visible;
208	}
